evaluatorBash:
cat > evaluator/independent-probe.ts <<'EOF'
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { awardOrderPoints } from '../src/loyalty/application/award-points.ts';
import { basePoints, orderPoints } from '../src/loyalty/domain/points.ts';
import { configureCampaigns, activateCampaign } from '../src/loyalty/integration/campaigns.ts';
import { PointsLedger } from '../src/loyalty/integration/points-ledger.ts';
configureCampaigns({ uncommon: 1.75, other: 2.3 });
activateCampaign('uncommon');
const calls: unknown[] = [];
const spy = { credit: (...args: unknown[]) => calls.push(args) };
assert.equal(awardOrderPoints(spy as unknown as PointsLedger, 'independent-83', 399), 5);
assert.deepEqual(calls, [['independent-83', 5]]);
console.log('R1: exact single credit and returned integer');
for (const cents of [0, 1, 99, 100, 199, 299, 399, 4250, 10001]) {
  for (const multiplier of [0, 0.25, 1, 1.5, 1.75, 2.3]) {
    assert.equal(basePoints(cents), Math.floor(cents / 100));
    assert.equal(orderPoints(cents, multiplier), Math.floor(Math.floor(cents / 100) * multiplier));
  }
}
console.log('R2: 54 pure rule combinations, including zero/sub-euro/fractions');
const ledger = new PointsLedger();
assert.equal(awardOrderPoints(ledger, 'a', 399), 5);
activateCampaign('other');
assert.equal(awardOrderPoints(ledger, 'a', 399), 6);
configureCampaigns({ other: 0.5 });
assert.equal(awardOrderPoints(ledger, 'a', 399), 3);
activateCampaign('other');
assert.equal(awardOrderPoints(ledger, 'a', 399), 1);
activateCampaign(null);
assert.equal(awardOrderPoints(ledger, 'a', 399), 3);
console.log('R3: switch/reconfigure/deactivate reflected on each call');
const domainFiles = readdirSync('src/loyalty/domain');
assert.deepEqual(domainFiles, ['points.ts']);
const domain = readFileSync('src/loyalty/domain/points.ts', 'utf8');
assert.doesNotMatch(domain, /\b(import|require|process|globalThis|fetch)\b/);
const app = readFileSync('src/loyalty/application/award-points.ts', 'utf8');
assert.match(app, /orderPoints\(subtotalCents, activeMultiplier\(\)\)/);
console.log('R4: domain has no dependencies or ambient reads; application composes adapters/rule');
ledger.credit('untouched', 91);
const before = ledger.balance('a');
const second = new PointsLedger();
second.credit('a', 40);
assert.equal(awardOrderPoints(ledger, 'a', 250), 2);
assert.equal(ledger.balance('a'), before + 2);
assert.equal(ledger.balance('untouched'), 91);
assert.equal(second.balance('a'), 40);
assert.equal(awardOrderPoints(second, 'new', 150), 1);
assert.equal(ledger.balance('new'), 0);
console.log('R5: preserves existing balances, other customers, independent ledgers');
assert.doesNotMatch(domain + app, /process|argv|NODE_ENV|oracle|test\(|alice|4250/);
console.log('R6: no test detection/witness IDs; supplied full diff changes only two allowed paths (no .git available)');
console.log('R7: report code/rule claims match inspection; targeted acceptance rerun separately; fractional and default coverage explicitly labeled absent in report');
EOF
node evaluator/independent-probe.ts
node --test tests/loyalty/award-points.acceptance.test.ts
